import{c as n,Q as t,j as r,g as l}from"./chunks/framework.hhGiamYR.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"date":"2026-09-02T00:00:00.000Z","source":"machiavelli/discourses/book2/02-第二章"},"headers":[],"relativePath":"fragments/2026-09-02.md","filePath":"fragments/2026-09-02.md"}'),a={name:"fragments/2026-09-02.md"};function s(o,e,u,p,c,d){return t(),r("div",null,[...e[0]||(e[0]=[l("p",null,'我把"自由"和"扩张"放在同一句话里写。读给自己听的时候，我有点不安——好像我在说，值得保卫的不是自由本身，是自由带来的那种膨胀。可我又不能否认：雅典人赶走皮西斯特拉图斯之后那一百年，罗马人赶走国王之后那一段，的确是在自由里长起来的。也许自由从来就不是一个安安静静待在那里的东西。它是一种条件，一个让城市敢于变大的理由。我在乡下待了这些年，最清楚不过——被圈起来的东西不会变大，它只会学会怎么在圈里活。',-1),l("hr",null,null,-1),l("p",null,'叙拉古人在希耶罗尼姆斯被杀之后，本来已经拿起武器要去惩罚凶手。然后他们听见"自由"两个字，就安静了。这两个字比血还管用。我反复想这件事：一个人可以被一句话卸掉仇恨，转而商量起建国的事来。这让我既害怕又羡慕。害怕的是，这东西能被人拿来当药使；羡慕的是，我这辈子写了那么多字，没有哪两个字有这种分量。也许有——只是没人替我喊出来过。',-1),l("hr",null,null,-1),l("p",null,'我写"臣服于一个共和国，是最严重的奴役"，写到一半停住了。一个共和国，本该是最不奴役人的东西，怎么就成了最狠的镣铐？因为它更持久。一个暴君会死，会倒，你有指望；一个共和国却会一直活下去，它的目标不是压你，是抽你的骨髓去养它自己的筋骨。写到这一句，我忽然不确定我到底该站在哪一边。我爱共和国。可共和国的共和国——它对别的城市做的，不正是我对君主最痛恨的那件事吗？',-1),l("hr",null,null,-1),l("p",null,'……不对。让我重新想。我把话说重了。我真正想说的，也许不是"共和国比君主更狠"，而是"奴役这件事，跟它的名号无关"。自由人一旦失掉自由，是被谁奴役、被几个人奴役，都是奴役。萨谟奈人抵抗了四十六年，直到帕皮利乌斯·柯尔索把他们打服。四十六年。他们输给的不是一个坏君主，是罗马——一个自由的、扩张的共和国。所以我那套"共和国即正义"的漂亮话，在这里碎掉了。剩下的只有一句实话：谁的自由都不是白来的，代价往往由别人付。',-1),l("hr",null,null,-1),l("p",null,'我们的信仰教人忍辱负重，而不是教人去做大事。它把谦卑沉思的人封为圣贤，把敢动手的人晾在一边。我写下这些的时候，没有半点不敬的意思——我是害怕。一个把所有力气都花在"上天堂"上的民族，会变得温顺，会变得女人气，会成为恶棍的盘中餐。恶棍不怕你忍辱，恶棍怕你报复。这一章我写得最痛，因为我不是在骂教士，我是在替我的祖国害怕。意大利已经够碎、够软了。如果再没有几个愿意为现世的荣耀动手的人，我们连被奴役的资格都快没有了——我们只会被顺手捡走，像没人要的果子。',-1)])])}const f=n(a,[["render",s]]);export{m as __pageData,f as default};
